<template>
  <el-dialog
    title="编辑场景基础信息"
    :visible.sync="showDialogVisible"
    width="520px"
    :before-close="handleClose"
  >
    <!-- <div :class="uploadClass">
      <vr-upload
        ref="upload"
        mode="scene"
        tip="最大支持30m以内的图片"
        :maxFileSize="maxFileSize"
        @onSuccess="onUploadSuccess"
      />
    </div>-->
    <el-form
      :model="model"
      :rules="rules"
      ref="model"
      label-width="100px"
      class="update-scene-form"
    >
      <el-form-item label="场景名称" prop="title">
        <el-input v-model="model.title"></el-input>
      </el-form-item>
      <!-- <el-form-item label="活动区域" prop="region">
    <el-select v-model="ruleForm.region" placeholder="请选择活动区域">
      <el-option label="区域一" value="shanghai"></el-option>
      <el-option label="区域二" value="beijing"></el-option>
    </el-select>
      </el-form-item>-->
    </el-form>
    <span slot="footer" class="dialog-footer">
      <el-button @click="cannel">取 消</el-button>
      <el-button type="primary" @click="save" :loading="saveLoading">保存</el-button>
    </span>
  </el-dialog>
</template>

<script>
// import VrUpload from '@/components/VrUpload'
import { updateScene } from '../../api/vr'
export default {
  name: 'UpdateSceneForm',
  props: {
    uploadClass: String
  },
  data() {
    return {
      showDialogVisible: false,
      path: '',
      maxFileSize: 30 * 1024 * 1024,
      saveLoading: false,
      productId: null,
      model: {
        id: null,
        title: ''
      },
      rules: {
        title: [
          { required: true, message: '请输入场景名称', trigger: 'blur' },
          {
            min: 3,
            max: 300,
            message: '长度在 3 到 300 个字符',
            trigger: 'blur'
          }
        ]
      }
    }
  },
  components: {
    // VrUpload
  },
  watch: {},
  created() {},
  methods: {
    open(productId, scene) {
      this.productId = productId
      this.$set(this.model, 'id', scene.id)
      this.$set(this.model, 'title', scene.name)
      this.showDialogVisible = true
    },
    cannel() {
      this.showDialogVisible = false
    },
    handleClose() {
      // this.$refs.upload.imageUrl = ''
      this.$refs.model.resetFields()
      this.model = Object.assign(
        {},
        {
          id: '',
          title: ''
        }
      )
      this.showDialogVisible = false
    },
    onUploadSuccess(result) {
      this.path = result.path
    },
    save() {
      // eslint-disable-next-line no-unused-vars
      updateScene(this.model.id, this.model).then(result => {
        this.cannel()
        this.$emit('onSceneUpdate')
      })
    }
  }
}
</script>

